BEGIN;
ALTER TABLE "Place" ADD COLUMN version integer NOT NULL DEFAULT 1 CHECK (version > 0), ADD COLUMN enabled boolean NOT NULL DEFAULT true;
CREATE TABLE "CatalogAdmin" (issuer varchar(128) NOT NULL, subject uuid NOT NULL, enabled boolean NOT NULL DEFAULT true, PRIMARY KEY(issuer,subject));
CREATE TABLE "PlaceRevision" ("placeId" varchar(80) NOT NULL REFERENCES "Place"(id) ON DELETE RESTRICT, version integer NOT NULL CHECK(version>0), snapshot jsonb NOT NULL, enabled boolean NOT NULL, "actorIssuer" varchar(128), "actorSubject" uuid, "createdAt" timestamptz(3) NOT NULL DEFAULT now(), PRIMARY KEY("placeId",version));
INSERT INTO "PlaceRevision" ("placeId",version,snapshot,enabled) SELECT id,version,snapshot,enabled FROM "Place";
ALTER TABLE "CatalogAdmin" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "CatalogAdmin" FORCE ROW LEVEL SECURITY;
CREATE POLICY own_admin ON "CatalogAdmin" FOR SELECT TO goease_app USING (issuer=current_setting('goease.issuer',true) AND subject=NULLIF(current_setting('goease.subject',true),'')::uuid);
GRANT SELECT ON "CatalogAdmin" TO goease_app;
ALTER TABLE "Place" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Place" FORCE ROW LEVEL SECURITY;
CREATE POLICY catalog_read ON "Place" FOR SELECT TO goease_app USING (true);
CREATE POLICY catalog_create ON "Place" FOR INSERT TO goease_app WITH CHECK (EXISTS(SELECT 1 FROM "CatalogAdmin" WHERE enabled AND issuer=current_setting('goease.issuer',true) AND subject=NULLIF(current_setting('goease.subject',true),'')::uuid));
CREATE POLICY catalog_update ON "Place" FOR UPDATE TO goease_app USING (EXISTS(SELECT 1 FROM "CatalogAdmin" WHERE enabled AND issuer=current_setting('goease.issuer',true) AND subject=NULLIF(current_setting('goease.subject',true),'')::uuid)) WITH CHECK (EXISTS(SELECT 1 FROM "CatalogAdmin" WHERE enabled AND issuer=current_setting('goease.issuer',true) AND subject=NULLIF(current_setting('goease.subject',true),'')::uuid));
GRANT INSERT,UPDATE ON "Place" TO goease_app;
ALTER TABLE "PlaceRevision" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "PlaceRevision" FORCE ROW LEVEL SECURITY;
CREATE POLICY revision_read ON "PlaceRevision" FOR SELECT TO goease_app USING (EXISTS(SELECT 1 FROM "CatalogAdmin" WHERE enabled AND issuer=current_setting('goease.issuer',true) AND subject=NULLIF(current_setting('goease.subject',true),'')::uuid));
CREATE POLICY revision_insert ON "PlaceRevision" FOR INSERT TO goease_app WITH CHECK ("actorIssuer"=current_setting('goease.issuer',true) AND "actorSubject"=NULLIF(current_setting('goease.subject',true),'')::uuid AND EXISTS(SELECT 1 FROM "CatalogAdmin" WHERE enabled AND issuer=current_setting('goease.issuer',true) AND subject=NULLIF(current_setting('goease.subject',true),'')::uuid));
GRANT SELECT,INSERT ON "PlaceRevision" TO goease_app;
COMMIT;
